cd /tmp && python -c "
import copy

# Simplified version of the clone function with the fix
def clone_fixed(estimator, safe=True):
    estimator_type = type(estimator)
    if estimator_type in (list, tuple, set, frozenset):
        return estimator_type([clone_fixed(e, safe=safe) for e in estimator])
    elif not hasattr(estimator, 'get_params') or isinstance(estimator, type):
        if not safe:
            return copy.deepcopy(estimator)
        else:
            raise TypeError('Cannot clone object')
    # This part would fail for a class since get_params needs self
    klass = estimator.__class__
    new_object_params = estimator.get_params(deep=False)
    for name, param in new_object_params.items():
        new_object_params[name] = clone_fixed(param, safe=False)
    new_object = klass(**new_object_params)
    return new_object


# Create a mock estimator class for testing
class MockEstimator:
    def __init__(self, param=None):
        self.param = param

    def get_params(self, deep=True):
        return {'param': self.param}

    def set_params(self, **params):
        for key, value in params.items():
            setattr(self, key, value)
        return self


# Test 1: Clone an instance - should work
print('Test 1: Clone an instance')
result = clone_fixed(MockEstimator())
print('  Success!', result)

# Test 2: Clone with a class as parameter - this is the bug case
print('Test 2: Clone with a class as parameter')
result = clone_fixed(MockEstimator(param=MockEstimator))
print('  Success!', result)
print('  param value:', result.param)

# Test 3: Clone a class directly with safe=False - should deepcopy
print('Test 3: Clone a class directly with safe=False')
result = clone_fixed(MockEstimator, safe=False)
print('  Success!', result)

# Test 4: Clone a class directly with safe=True - should raise error
print('Test 4: Clone a class directly with safe=True')
try:
    result = clone_fixed(MockEstimator, safe=True)
    print('  ERROR: Should have raised an exception')
except TypeError as e:
    print('  Correctly raised TypeError:', str(e))
"

